Method.Source:
   /// <summary>
   /// control method for METChange button
   /// </summary>
   /// <param name = "sender">Form</param>
   /// <param name = "e">form arguments</param>
   [
       FormControlEventHandler(formControlStr(OMLegalEntity, METChange), FormControlEventType::Clicked),
       SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface'),
       SuppressBPWarningAttribute('BPUpgradeCodeLateBoundCall', 'Standard call')
   ]
   public static void METChange_OnClicked(FormControl sender, FormControlEventArgs e)
   {
       FormRun             formRun         = sender.formRun();
       FormControl         metLogoImage    = formRun.design().controlName(formControlStr(OMLegalEntity, METLogoImage));

       if (formRun.metUploadImageFile())
       {
           formRun.parmImageContainer(ImageReference::GetPackedBinaryData(formRun.parmimageFilePathName()));
           formRun.metShowImage(metLogoImage);
           formRun.metInsertImage(metLogoImage, METCompanyImageType::CompanyLogo);
       }
   }

    /// <summary>
    /// control method for METRemove button
    /// </summary>
    /// <param name = "sender">Form</param>
    /// <param name = "e">form arguments</param>
    [
        FormControlEventHandler(formControlStr(OMLegalEntity, METRemove), FormControlEventType::Clicked),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface'),
        SuppressBPWarningAttribute('BPUpgradeCodeLateBoundCall', 'Standard call')
    ]
    public static void METRemove_OnClicked(FormControl sender, FormControlEventArgs e)
    {
        FormRun             formRun         = sender.formRun();
        FormControl         metLogoImage    = formRun.design().controlName(formControlStr(OMLegalEntity, METLogoImage));

        formRun.metDeleteImage(metLogoImage,  METCompanyImageType::CompanyLogo);
    }
